-- Synthetic integration schema. Never run this file against an OD database.
CREATE TABLE patient (PatNum BIGINT PRIMARY KEY, FName VARCHAR(100), LName VARCHAR(100), ClinicNum BIGINT) ENGINE=InnoDB;
CREATE TABLE definition (DefNum BIGINT PRIMARY KEY, Category INT, ItemName VARCHAR(100), IsHidden TINYINT) ENGINE=InnoDB;
CREATE TABLE procedurelog (ProcNum BIGINT PRIMARY KEY, PatNum BIGINT, CodeNum BIGINT, ProvNum BIGINT, ClinicNum BIGINT, ProcStatus INT, ProcDate DATE, ToothNum VARCHAR(10), ProcFee DOUBLE, INDEX(PatNum)) ENGINE=InnoDB;
CREATE TABLE procedurecode (CodeNum BIGINT PRIMARY KEY, ProcCode VARCHAR(20), Descript VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE provider (ProvNum BIGINT PRIMARY KEY, Abbr VARCHAR(20)) ENGINE=InnoDB;
CREATE TABLE payment (PayNum BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, PayType BIGINT NOT NULL, PayDate DATE NOT NULL, PayAmt DOUBLE NOT NULL, CheckNum VARCHAR(100) NOT NULL, BankBranch VARCHAR(100) NOT NULL, PayNote TEXT NOT NULL, IsSplit TINYINT NOT NULL, PatNum BIGINT NOT NULL, ClinicNum BIGINT NOT NULL, DateEntry DATE NOT NULL, DepositNum BIGINT NOT NULL, Receipt TEXT NOT NULL, IsRecurringCC TINYINT NOT NULL, SecUserNumEntry BIGINT NOT NULL, SecDateTEdit TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PaymentSource INT NOT NULL, ProcessStatus INT NOT NULL, RecurringChargeDate DATE NOT NULL, INDEX(PatNum)) ENGINE=InnoDB;
CREATE TABLE paysplit (SplitNum BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, SplitAmt DOUBLE NOT NULL, PatNum BIGINT NOT NULL, ProcDate DATE NOT NULL, PayNum BIGINT NOT NULL, IsDiscount TINYINT NOT NULL, DiscountType INT NOT NULL, ProvNum BIGINT NOT NULL, PayPlanNum BIGINT NOT NULL, DatePay DATE NOT NULL, ProcNum BIGINT NOT NULL, DateEntry DATE NOT NULL, UnearnedType BIGINT NOT NULL, ClinicNum BIGINT NOT NULL, SecUserNumEntry BIGINT NOT NULL, FSplitNum BIGINT NOT NULL, AdjNum BIGINT NOT NULL, PayPlanChargeNum BIGINT NOT NULL, INDEX(PatNum), INDEX(PayNum)) ENGINE=InnoDB;
CREATE TABLE claimproc (ClaimProcNum BIGINT PRIMARY KEY, PatNum BIGINT, ProcNum BIGINT, ClaimPaymentNum BIGINT, InsPayAmt DOUBLE, INDEX(PatNum)) ENGINE=InnoDB;
CREATE TABLE claimpayment (ClaimPaymentNum BIGINT PRIMARY KEY, CheckDate DATE, CheckAmt DOUBLE, CheckNum VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE preference (PrefName VARCHAR(100) PRIMARY KEY, ValueString TEXT) ENGINE=InnoDB;
CREATE TABLE userod (UserNum BIGINT PRIMARY KEY, IsHidden TINYINT) ENGINE=InnoDB;
CREATE TABLE patplan (PatPlanNum BIGINT PRIMARY KEY, PatNum BIGINT, InsSubNum BIGINT) ENGINE=InnoDB;
CREATE TABLE inssub (InsSubNum BIGINT PRIMARY KEY, PlanNum BIGINT, Subscriber BIGINT) ENGINE=InnoDB;
CREATE TABLE insplan (PlanNum BIGINT PRIMARY KEY, CarrierNum BIGINT) ENGINE=InnoDB;
CREATE TABLE carrier (CarrierNum BIGINT PRIMARY KEY, CarrierName VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE document (DocNum BIGINT PRIMARY KEY, PatNum BIGINT) ENGINE=InnoDB;
CREATE TABLE claim (ClaimNum BIGINT PRIMARY KEY, PatNum BIGINT) ENGINE=InnoDB;
CREATE TABLE adjustment (AdjNum BIGINT PRIMARY KEY, PatNum BIGINT) ENGINE=InnoDB;
CREATE TABLE clinic (ClinicNum BIGINT PRIMARY KEY, Abbr VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE securitylog (SecurityLogNum BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, PermType INT NOT NULL, UserNum BIGINT NOT NULL, LogDateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, LogText TEXT NOT NULL, PatNum BIGINT NOT NULL, CompName VARCHAR(255) NOT NULL, FKey BIGINT NOT NULL, LogSource INT NOT NULL, DefNum BIGINT NOT NULL, DefNumError BIGINT NOT NULL, DateTPrevious DATETIME NOT NULL, INDEX(PatNum)) ENGINE=InnoDB;
CREATE TABLE securityloghash (SecurityLogHashNum BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, SecurityLogNum BIGINT NOT NULL, LogHash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
